/**
 * Compact, agent-friendly views of a session's NDJSON event stream.
 *
 * Coding agents (and eval harnesses) want a stable JSON shape: user
 * messages, assistant text, tool calls with args/results, and
 * success/failure — not a firehose of streaming deltas.
 */
import { readFile } from "node:fs/promises";
import { isSessionEvent } from "./json-value.js";
/**
 * Collapse a session event list into a trajectory. Streaming deltas are
 * folded into final assistant / reasoning text per turn.
 */
export function buildTrajectory(events) {
    let sessionId = "";
    let sdkAgentId;
    let agentUrl;
    let channelId;
    const turnsById = new Map();
    const turnOrder = [];
    const pendingCalls = new Map();
    const ensureTurn = (turnId) => {
        const existing = turnsById.get(turnId);
        if (existing !== undefined) {
            return existing;
        }
        const turn = {
            turnId,
            assistantText: "",
            toolCalls: [],
            subagents: [],
            failed: false,
        };
        turnsById.set(turnId, turn);
        turnOrder.push(turnId);
        return turn;
    };
    for (const event of events) {
        if (sessionId === "" && typeof event.sessionId === "string") {
            sessionId = event.sessionId;
        }
        switch (event.type) {
            case "session.started": {
                channelId = event.data.channelId;
                break;
            }
            case "agent.bound": {
                sdkAgentId = event.data.sdkAgentId;
                agentUrl = event.data.url;
                break;
            }
            case "message.received": {
                if (event.turnId !== undefined) {
                    ensureTurn(event.turnId).userMessage = event.data.text;
                }
                break;
            }
            case "message.completed": {
                // Nested subagent text must not overwrite the parent turn reply.
                if (event.data.parentCallId !== undefined) {
                    break;
                }
                if (event.turnId !== undefined && event.data.text !== "") {
                    ensureTurn(event.turnId).assistantText = event.data.text;
                }
                break;
            }
            case "reasoning.appended": {
                // Nested subagent thinking stays off the parent turn transcript.
                if (event.data.parentCallId !== undefined) {
                    break;
                }
                if (event.turnId !== undefined) {
                    ensureTurn(event.turnId).reasoningText = event.data.text;
                }
                break;
            }
            case "actions.requested": {
                if (event.turnId === undefined) {
                    break;
                }
                const turn = ensureTurn(event.turnId);
                for (const call of event.data.calls) {
                    const parentCallId = call.parentCallId ?? event.data.parentCallId;
                    // Keep bare top-level `task` in toolCalls so evals like
                    // `calledTool("task")` / `notCalledTool("task")` keep working.
                    // Nested progress also appears under `subagents`.
                    const entry = {
                        callId: call.callId,
                        toolName: call.toolName,
                        isError: false,
                        args: call.args,
                        parentCallId,
                    };
                    pendingCalls.set(call.callId, entry);
                    if (parentCallId !== undefined) {
                        let sub = turn.subagents.find((s) => s.callId === parentCallId);
                        if (sub === undefined) {
                            sub = { callId: parentCallId, toolCalls: [] };
                            turn.subagents.push(sub);
                        }
                        sub.toolCalls.push(entry);
                    }
                    else {
                        turn.toolCalls.push(entry);
                    }
                }
                break;
            }
            case "action.approval_requested": {
                // Traceability only — the call is already listed under actions.requested.
                break;
            }
            case "action.approval_resolved": {
                const pending = pendingCalls.get(event.data.callId);
                if (pending !== undefined) {
                    pending.approvalDecision = event.data.decision;
                }
                break;
            }
            case "action.auth_requested": {
                break;
            }
            case "action.auth_resolved": {
                const pending = pendingCalls.get(event.data.callId);
                if (pending !== undefined) {
                    pending.approvalDecision = event.data.decision;
                }
                break;
            }
            case "action.result": {
                const pending = pendingCalls.get(event.data.callId);
                if (pending !== undefined) {
                    pending.output = event.data.output;
                    pending.isError = event.data.isError;
                    pending.toolName = event.data.toolName;
                }
                else if (event.turnId !== undefined) {
                    const turn = ensureTurn(event.turnId);
                    const entry = {
                        callId: event.data.callId,
                        toolName: event.data.toolName,
                        output: event.data.output,
                        isError: event.data.isError,
                        parentCallId: event.data.parentCallId,
                    };
                    if (event.data.parentCallId !== undefined) {
                        let sub = turn.subagents.find((s) => s.callId === event.data.parentCallId);
                        if (sub === undefined) {
                            sub = {
                                callId: event.data.parentCallId,
                                toolCalls: [],
                            };
                            turn.subagents.push(sub);
                        }
                        sub.toolCalls.push(entry);
                    }
                    else {
                        turn.toolCalls.push(entry);
                    }
                }
                break;
            }
            case "subagent.called": {
                if (event.turnId !== undefined) {
                    const turn = ensureTurn(event.turnId);
                    const existing = turn.subagents.find((s) => s.callId === event.data.callId);
                    if (existing !== undefined) {
                        existing.name = event.data.name;
                        existing.description = event.data.description;
                    }
                    else {
                        turn.subagents.push({
                            callId: event.data.callId,
                            name: event.data.name,
                            description: event.data.description,
                            toolCalls: [],
                        });
                    }
                }
                break;
            }
            case "turn.completed": {
                if (event.turnId === undefined) {
                    break;
                }
                const turn = ensureTurn(event.turnId);
                turn.failed = false;
                if (event.data.usage !== undefined) {
                    turn.usage = event.data.usage;
                }
                if (event.data.result !== undefined) {
                    turn.result = event.data.result;
                    if (turn.assistantText === "") {
                        turn.assistantText = event.data.result;
                    }
                }
                break;
            }
            case "turn.failed": {
                if (event.turnId !== undefined) {
                    const turn = ensureTurn(event.turnId);
                    turn.failed = true;
                    turn.error = event.data.message;
                }
                break;
            }
            case "session.failed": {
                if (event.turnId !== undefined) {
                    const turn = ensureTurn(event.turnId);
                    turn.failed = true;
                    turn.error = event.data.message;
                }
                break;
            }
            default:
                break;
        }
    }
    const turns = turnOrder.map((id) => turnsById.get(id));
    const turnsFailed = turns.filter((t) => t.failed).length;
    const toolCallCount = turns.reduce((n, t) => n + t.toolCalls.length + t.subagents.reduce((m, s) => m + s.toolCalls.length, 0), 0);
    const lastGood = [...turns].reverse().find((t) => t.assistantText !== "");
    return {
        sessionId,
        ...(sdkAgentId === undefined ? {} : { sdkAgentId }),
        ...(agentUrl === undefined ? {} : { agentUrl }),
        ...(channelId === undefined ? {} : { channelId }),
        ok: turnsFailed === 0 && turns.length > 0,
        finalText: lastGood?.assistantText ?? "",
        turnsFailed,
        toolCallCount,
        turns,
    };
}
/** Compact dollar display for estimated costs (`$0.0132`, `$1.25`). */
export function formatCostUsd(usd) {
    if (!Number.isFinite(usd)) {
        return "—";
    }
    if (usd === 0) {
        return "$0.00";
    }
    if (usd >= 0.1) {
        return `$${usd.toFixed(2)}`;
    }
    return `$${usd.toFixed(4)}`;
}
/** Parse an `events.ndjson` file (or any NDJSON blob of SessionEvents). */
export function parseEventsNdjson(text) {
    const events = [];
    for (const line of text.split("\n")) {
        const trimmed = line.trim();
        if (trimmed === "") {
            continue;
        }
        try {
            const parsed = JSON.parse(trimmed);
            if (isSessionEvent(parsed)) {
                events.push(parsed);
            }
        }
        catch {
            // skip malformed lines
        }
    }
    return events;
}
/** Load and summarize a durable session event log. */
export async function loadTrajectoryFromEventsFile(path) {
    const text = await readFile(path, "utf8");
    return buildTrajectory(parseEventsNdjson(text));
}
/** Human-readable one-line-per-turn dump (for non-JSON CLI output). */
export function formatTrajectoryText(trajectory) {
    const lines = [];
    lines.push(`session ${trajectory.sessionId || "(unknown)"}  ok=${trajectory.ok}`);
    if (trajectory.sdkAgentId !== undefined) {
        lines.push(`sdkAgentId: ${trajectory.sdkAgentId}`);
    }
    if (trajectory.agentUrl !== undefined) {
        lines.push(`url: ${trajectory.agentUrl}`);
    }
    lines.push(`turns: ${trajectory.turns.length}  tools=${trajectory.toolCallCount}  failed: ${trajectory.turnsFailed}${trajectory.totalCostUsd === undefined
        ? ""
        : `  cost: ${formatCostUsd(trajectory.totalCostUsd)}`}`);
    for (const turn of trajectory.turns) {
        lines.push("");
        lines.push(`── ${turn.turnId}${turn.failed ? " FAILED" : ""} ──`);
        if (turn.userMessage !== undefined) {
            lines.push(`  user: ${truncate(turn.userMessage, 200)}`);
        }
        for (const call of turn.toolCalls) {
            const mark = call.isError ? "✗" : "→";
            lines.push(`  ${mark} ${call.toolName}${formatArgs(call.args)}`);
            if (call.output !== undefined) {
                lines.push(`    ${truncate(stringify(call.output), 160)}`);
            }
        }
        for (const sub of turn.subagents) {
            const label = sub.name ?? "subagent";
            const detail = sub.description !== undefined ? ` — ${truncate(sub.description, 80)}` : "";
            lines.push(`  task ${label}${detail}`);
            for (const call of sub.toolCalls) {
                const mark = call.isError ? "✗" : "→";
                lines.push(`    ${mark} ${call.toolName}${formatArgs(call.args)}`);
                if (call.output !== undefined) {
                    lines.push(`      ${truncate(stringify(call.output), 160)}`);
                }
            }
        }
        if (turn.assistantText.length > 0) {
            lines.push(`  agent: ${truncate(turn.assistantText, 400)}`);
        }
        if (turn.error !== undefined) {
            lines.push(`  error: ${turn.error}`);
        }
        if (turn.usage !== undefined) {
            lines.push(`  usage: in ${turn.usage.inputTokens} out ${turn.usage.outputTokens}`);
        }
    }
    return `${lines.join("\n")}\n`;
}
function stringify(value) {
    if (value === undefined || value === null) {
        return "(no output)";
    }
    return typeof value === "string" ? value : JSON.stringify(value);
}
function formatArgs(args) {
    if (args === undefined || args === null) {
        return "";
    }
    const text = typeof args === "string" ? args : JSON.stringify(args);
    return text === "{}" ? "" : `(${truncate(text, 80)})`;
}
function truncate(text, max) {
    const oneLine = text.replace(/\s+/g, " ").trim();
    return oneLine.length > max ? `${oneLine.slice(0, max - 1)}…` : oneLine;
}
